import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Paper,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  IconButton,
  TextField,
  InputAdornment,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Grid,
  CircularProgress
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import Layout from '../components/Layout';
import { moviesAPI } from '../services/api';

const parseDuration = (isoDuration) => {
  if (!isoDuration || typeof isoDuration !== 'string') return 0;
  const hourMatch = isoDuration.match(/(\d+)H/);
  const minuteMatch = isoDuration.match(/(\d+)M/);
  const hours = hourMatch ? parseInt(hourMatch[1], 10) : 0;
  const minutes = minuteMatch ? parseInt(minuteMatch[1], 10) : 0;
  return hours * 60 + minutes;
};

const toIsoDuration = (minutes) => {
  const mins = parseInt(minutes, 10);
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `PT${h > 0 ? `${h}H` : ''}${m > 0 ? `${m}M` : ''}` || 'PT0M';
};

const MoviesManagement = () => {
  const [loading, setLoading] = useState(true);
  const [movies, setMovies] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [openEditDialog, setOpenEditDialog] = useState(false);
  const [openAddDialog, setOpenAddDialog] = useState(false);
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [saving, setSaving] = useState(false);

  const defaultMovieState = {
    title: '',
    duration: '',
    PosterURL: '',
    description: '',
    releaseDate: ''
  };

  const [movieForm, setMovieForm] = useState(defaultMovieState);

  useEffect(() => {
    const fetchMovies = async () => {
      try {
        setLoading(true);
        const data = await moviesAPI.getAllMovies();
        const mapped = data.map(m => ({
          ...m,
          duration: typeof m.duration === 'string' ? parseDuration(m.duration) : m.duration
        }));
        setMovies(mapped);
      } catch (err) {
        console.error('Fetch error:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchMovies();
  }, []);

  const handleOpenEdit = (movie) => {
    setSelectedMovie(movie);
    setMovieForm({ ...movie });
    setOpenEditDialog(true);
  };

  const handleCloseEdit = () => {
    setOpenEditDialog(false);
    setMovieForm(defaultMovieState);
  };

  const handleSave = async () => {
    if (!movieForm.title || !movieForm.duration) {
      alert('Vui lòng nhập đầy đủ thông tin.');
      return;
    }

    const payload = {
      title: movieForm.title,
      duration: toIsoDuration(movieForm.duration),
      PosterURL: movieForm.PosterURL,
      description: movieForm.description
    };

    try {
      setSaving(true);
      if (selectedMovie) {
        await moviesAPI.updateMovie(selectedMovie.id, payload);
      } else {
        await moviesAPI.createMovie(payload);
      }
      const refreshed = await moviesAPI.getAllMovies();
      const mapped = refreshed.map(m => ({
        ...m,
        duration: typeof m.duration === 'string' ? parseDuration(m.duration) : m.duration
      }));
      setMovies(mapped);
      setOpenAddDialog(false);
      setOpenEditDialog(false);
    } catch (err) {
      console.error('Save error:', err);
      alert('Lỗi khi lưu phim.');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id) => {
    try {
      await moviesAPI.deleteMovie(id);
      setMovies(movies.filter(m => m.id !== id));
    } catch (err) {
      console.error('Delete error:', err);
    }
  };

  return (
    <Layout>
      <Box sx={{ p: 2 }}>
        <Typography variant="h4">Quản lý phim</Typography>
        <Button variant="contained" startIcon={<AddIcon />} sx={{ my: 2 }} onClick={() => setOpenAddDialog(true)}>
          Thêm phim
        </Button>
        <TextField
          placeholder="Tìm kiếm phim"
          fullWidth
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            )
          }}
          sx={{ mb: 2 }}
        />

        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>ID</TableCell>
                <TableCell>Tên</TableCell>
                <TableCell>Thời lượng (phút)</TableCell>
                <TableCell>Hành động</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {movies.filter(m => m.title.toLowerCase().includes(searchTerm.toLowerCase())).map((movie) => (
                <TableRow key={movie.id}>
                  <TableCell>{movie.id}</TableCell>
                  <TableCell>{movie.title}</TableCell>
                  <TableCell>{movie.duration}</TableCell>
                  <TableCell>
                    <IconButton onClick={() => handleOpenEdit(movie)}><EditIcon /></IconButton>
                    <IconButton onClick={() => handleDelete(movie.id)}><DeleteIcon color="error" /></IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Dialog open={openEditDialog || openAddDialog} onClose={() => {setOpenEditDialog(false); setOpenAddDialog(false);}}>
          <DialogTitle>{selectedMovie ? 'Chỉnh sửa phim' : 'Thêm phim mới'}</DialogTitle>
          <DialogContent>
            <TextField fullWidth label="Tên phim" value={movieForm.title} onChange={(e) => setMovieForm({ ...movieForm, title: e.target.value })} sx={{ my: 1 }} />
            <TextField fullWidth label="Thời lượng (phút)" type="number" value={movieForm.duration} onChange={(e) => setMovieForm({ ...movieForm, duration: e.target.value })} sx={{ my: 1 }} />
            <TextField fullWidth label="Mô tả" multiline rows={3} value={movieForm.description} onChange={(e) => setMovieForm({ ...movieForm, description: e.target.value })} sx={{ my: 1 }} />
            <TextField fullWidth label="Poster URL" value={movieForm.PosterURL} onChange={(e) => setMovieForm({ ...movieForm, PosterURL: e.target.value })} sx={{ my: 1 }} />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => { setOpenEditDialog(false); setOpenAddDialog(false); }}>Hủy</Button>
            <Button variant="contained" onClick={handleSave} disabled={saving}>{saving ? 'Đang lưu...' : 'Lưu'}</Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Layout>
  );
};

export default MoviesManagement;
